"use client"

import { useEffect, useState } from "react"
import { useNavigate } from "react-router-dom"
import axios from "axios"
import {
  ChefHat,
  GraduationCap,
  Building2,
  DollarSign,
  TrendingUp,
  AlertCircle,
  Loader2,
  ArrowUpRight,
  Eye,
  FileText,
  Package,
} from "lucide-react"
import Layout from "./Layout"

// Import Chart.js components for Doughnut chart
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from "chart.js"
import { Doughnut } from "react-chartjs-2"

// Register Chart.js components
ChartJS.register(ArcElement, Tooltip, Legend)

export default function Dashboard() {
  const [stats, setStats] = useState({
    totalInterns: 0,
    totalChefs: 0,
    totalDeputyDirectors: 0,
    totalPayments: 0,
    totalReports: 0,
    recentReports: [],
    recentPayments: [],
    paymentsByMonth: [],
    paymentCompletion: 0,
    internsBySector: [],
    consumption: {
      total: 0,
      academicYear: "N/A",
    },
    payments: {
      total: 0,
      numberOfInterns: 0,
      averagePerIntern: 0,
      academicYear: "N/A",
      monthlyBreakdown: {},
    },
    inventory: {
      products: 0,
      lowStock: 0,
      expired: 0,
      recent: [],
    },
  })
  const navigate = useNavigate()
  const [userRole, setUserRole] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState("")

  // Helper function to parse DD/MM/YYYY or ISO dates
  const parseDate = (dateStr) => {
    if (!dateStr) return null
    // Try parsing as ISO first
    let parsedDate = new Date(dateStr)
    if (!isNaN(parsedDate)) return parsedDate
    // Try parsing as DD/MM/YYYY
    const [day, month, year] = dateStr.split("/")
    if (!day || !month || !year) return null
    parsedDate = new Date(`${year}-${month}-${day}`)
    return isNaN(parsedDate) ? null : parsedDate
  }

  useEffect(() => {
    const token = localStorage.getItem("token")
    const role = localStorage.getItem("role")
    if (!token || !role) {
      navigate("/")
    } else {
      setUserRole(role)
      fetchDashboardData(token)
    }
  }, [navigate])

  const fetchDashboardData = async (token) => {
    setIsLoading(true)
    setError("")
    try {
      const [
        internsResponse,
        chefsResponse,
        directorsResponse,
        reportsResponse,
        paymentsResponse,
        consumptionResponse,
        totalPaymentsResponse,
        inventoryResponse,
      ] = await Promise.all([
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/interns`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: { data: [] } })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/chefs`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: [] })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/deputydirectors`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: [] })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/reports`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: { data: [] } })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/payments`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: { data: [] } })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/interns/totalConsumption`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({
            data: { data: { totalConsumption: 0, academicYear: "N/A" } },
          })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/payments/total`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({
            data: {
              data: { totalAmount: 0, numberOfInterns: 0, averagePerIntern: 0, monthlyBreakdown: {} },
            },
          })),
        axios
          .get(`${process.env.REACT_APP_API_URL}/api/products`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Superadmin" },
          })
          .catch(() => ({ data: [] })),
      ])

      const interns = internsResponse.data.data || []
      const chefs = chefsResponse.data || []
      const directors = directorsResponse.data || []
      const reports = reportsResponse.data.data || []
      const payments = paymentsResponse.data.data || []
      const consumption = consumptionResponse.data.data || {}
      const totalPayments = totalPaymentsResponse.data.data || {}
      const inventoryData = inventoryResponse.data || []

      // Process inventory data
      const today = new Date()
      today.setHours(0, 0, 0, 0) // Normalize to start of day

      const lowStockProducts = inventoryData.filter((product) => product.quantity < 50)
      const expiredProducts = inventoryData.filter((product) => {
        if (!product.expirationDate) return false
        const expiryDate = parseDate(product.expirationDate)
        if (!expiryDate) {
          /* eslint-disable */console.log(...oo_oo(`41950507_167_10_167_110_4`,`Invalid expiration date for product ${product.nameProduct}: ${product.expirationDate}`))
          return false
        }
        return expiryDate < today
      })
      const recentProducts = inventoryData.slice(0, 5).map((product) => ({
        id: product._id,
        name: product.nameProduct,
        quantity: product.quantity,
        price: product.priceForOne,
        expiryDate: product.expirationDate
          ? parseDate(product.expirationDate)?.toLocaleDateString("fr-FR") || "N/A"
          : "N/A",
      }))

      // Log for debugging
      /* eslint-disable */console.log(...oo_oo(`41950507_183_6_183_55_4`,"Expired Products:", expiredProducts))
      /* eslint-disable */console.log(...oo_oo(`41950507_184_6_184_58_4`,"Low Stock Products:", lowStockProducts))

      // Process other data
      const sectors = {}
      interns.forEach((intern) => {
        if (intern.Sector) {
          sectors[intern.Sector] = (sectors[intern.Sector] || 0) + 1
        }
      })
      const internsBySector = Object.keys(sectors).map((key) => ({
        name: key,
        value: sectors[key],
      }))

      const totalMonths = payments.length * 12
      let paidMonths = 0
      payments.forEach((payment) => {
        if (payment.payments) {
          Object.values(payment.payments).forEach((amount) => {
            if (amount > 0) paidMonths++
          })
        }
      })
      const paymentCompletion = totalMonths > 0 ? Math.round((paidMonths / totalMonths) * 100) : 0

      const recentReports = reports.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)).slice(0, 5)
      const recentPayments = payments.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt)).slice(0, 5)

      const monthlyPayments = totalPayments.monthlyBreakdown || {}
      const paymentsByMonth = [
        monthlyPayments.September || 0,
        monthlyPayments.October || 0,
        monthlyPayments.November || 0,
        monthlyPayments.December || 0,
        monthlyPayments.January || 0,
        monthlyPayments.February || 0,
        monthlyPayments.March || 0,
        monthlyPayments.April || 0,
        monthlyPayments.May || 0,
        monthlyPayments.June || 0,
        monthlyPayments.July || 0,
        monthlyPayments.August || 0,
      ]

      setStats({
        totalInterns: interns.length,
        totalChefs: chefs.length,
        totalDeputyDirectors: directors.length,
        totalPayments: payments.reduce((sum, payment) => sum + (payment.totalAmount || 0), 0),
        totalReports: reports.length,
        recentReports,
        recentPayments,
        paymentsByMonth,
        paymentCompletion,
        internsBySector,
        consumption: {
          total: consumption.totalConsumption || 0,
          academicYear: consumption.academicYear || "N/A",
        },
        payments: {
