                    <span className="text-sm text-[#333333]">{stats.paymentCompletion}%</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2.5">
                    <div
                      className="bg-[#00717F] h-2.5 rounded-full"
                      style={{ width: `${stats.paymentCompletion}%` }}
                    ></div>
                  </div>
                  <div className="flex justify-between text-xs text-[#333333]">
                    <span>0%</span>
                    <span>50%</span>
                    <span>100%</span>
                  </div>
                </div>
                <div className="space-y-4">
                  <h3 className="text-sm font-medium text-[#333333]">Paiements Récents</h3>
                  <ul className="space-y-3">
                    {stats.recentPayments.slice(0, 3).map((payment, index) => (
                      <li key={index} className="flex items-center justify-between text-sm">
                        <div className="flex items-center">
                          <div className="h-8 w-8 rounded-full bg-[#F5F6FA] flex items-center justify-center mr-2">
                            <DollarSign className="h-4 w-4 text-[#00717F]" />
                          </div>
                          <span className="font-medium">
                            {payment.internId?.First_Name} {payment.internId?.Last_Name}
                          </span>
                        </div>
                        <span className="font-semibold text-[#4CAF50]">{payment.totalAmount} DH</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>

            {/* Gestion du Stock Section */}
            <div className="bg-[#F5F6FA] rounded-xl shadow-md border border-[#C8A45D]/30 overflow-hidden">
              <div className="bg-[#F5F6FA]/50 p-4">
                <div className="flex items-center gap-2">
                  <Package className="h-5 w-5 text-[#00717F]" />
                  <h2 className="text-lg font-semibold text-[#00717F]">Gestion du Stock</h2>
                </div>
              </div>
              <div className="p-4">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                  <div className="bg-[#F5F6FA]/50 p-3 rounded-lg">
